export const BODY: string = "\n<p>ڈی پی آئی کا مطلب ہے ڈاٹس پر انچ، اور یہ بتاتا ہے کہ پرنٹ کے ہر انچ میں کتنے پکسلز بھرے جائیں گے۔ بہت سے فارم اور پرنٹر 300 ڈی پی آئی مانگتے ہیں، اور اسی لیے ڈی پی آئی بدلنے والا ٹول کام آتا ہے۔</p>\n<p>سب سے اہم بات یہ ہے کہ ڈی پی آئی پکسلز نہیں بدلتا۔ یہ صرف فائل میں لکھا ایک عدد ہے، جو پرنٹر کو بتاتا ہے کہ تصویر کتنے بڑے کاغذ پر چھاپنی ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ ڈی پی آئی کیا ہے، کون سے پہلے سے طے شدہ عدد استعمال کریں، PNG کی 299 والی پہیلی کیوں ہوتی ہے، اور بیچ میں کیسے کام کریں۔ ٹول کھولنے کے لیے <a href=\"/ur/tasveer-ka-dpi-badlein/\">امیج ڈی پی آئی چینجر</a> پر جائیں۔</p>\n<h2 id=\"what-is-dpi\">ڈی پی آئی کیا ہے؟</h2>\n<p>ڈی پی آئی پرنٹ کی کثافت ہے: 300 ڈی پی آئی کا مطلب ہے کہ پرنٹ کے ہر انچ میں 300 پکسلز آئیں گے۔ زیادہ ڈی پی آئی کا مطلب چھوٹا مگر تیز پرنٹ ہے، کم ڈی پی آئی کا مطلب بڑا مگر نرم پرنٹ ہے۔</p>\n<p>اسکرین پر ڈی پی آئی کا کوئی اثر نہیں ہوتا، کیونکہ براؤزر صرف پکسلز دیکھتا ہے۔ ڈی پی آئی کی دنیا پرنٹ، فارم اور پبلشنگ کی دنیا ہے۔</p>\n<h2 id=\"dpi-is-metadata\">ڈی پی آئی میٹا ڈیٹا ہے، پکسلز نہیں</h2>\n<p>ڈی پی آئی بدلنے سے تصویر کے پکسلز، رنگ یا تیزرفتاری میں کچھ نہیں بدلتا۔ فائل کے اندر صرف ایک چھوٹا سا عدد لکھا جاتا ہے، جسے پرنٹر پڑھتا ہے۔</p>\n<p>اسی لیے ڈی پی آئی بدلنا فائل ہلکی یا تصویر تیز کرنے کا طریقہ نہیں ہے۔ یہ صرف پرنٹر اور فارم کو درست ہدایت دینے کا طریقہ ہے۔</p>\n<h2 id=\"dpi-presets-explained\">ڈی پی آئی پہلے سے طے شدہ عدد: 72 سے 600 تک</h2>\n<p>72 ڈی پی آئی اسکرین کا پرانا معیار ہے اور پرنٹ کے لیے بہت کم ہے۔ 150 ڈی پی آئی عام دستاویزات کے لیے کافی ہے، جبکہ 300 ڈی پی آئی معیاری پرنٹ کا معیار ہے۔</p>\n<p>600 ڈی پی آئی بہت باریک پرنٹ، جیسے کتاب کے سرورق یا میگزین کے صفحے، کے لیے استعمال ہوتا ہے۔ عام تصویر کے لیے 300 سے زیادہ کا کوئی فائدہ نہیں، کیونکہ آنکھ فرق نہیں پہچانتی۔</p>\n<h2 id=\"custom-dpi-range\">اپنی مرضی کی ڈی پی آئی: 1 سے 2400 تک کوئی بھی عدد</h2>\n<p>کبھی کبھی فارم کوئی غیر معمولی عدد مانگتا ہے، جیسے 200 یا 350 ڈی پی آئی۔ اپنی مرضی کی سیٹنگ میں آپ 1 سے 2400 تک کوئی بھی عدد لکھ سکتے ہیں۔</p>\n<p>عدد لکھتے وقت فارم کی ہدایت دوبارہ پڑھیں: کچھ فارم کم سے کم ڈی پی آئی مانگتے ہیں، کچھ بالکل درست عدد۔ غلط عدد بھی مسترد ہو سکتا ہے۔</p>\n<h2 id=\"jpeg-and-png-only\">کون سے فارمیٹ کام کرتے ہیں: JPEG اور PNG</h2>\n<p>ڈی پی آئی چینجر JPEG اور PNG فائلوں پر کام کرتا ہے، کیونکہ ان دونوں میں ڈی پی آئی لکھنے کی جگہ ہوتی ہے۔ WebP اور HEIC میں یہ سیٹنگ اس طرح محفوظ نہیں ہوتی۔</p>\n<p>اگر آپ کی فائل WebP ہے تو پہلے اسے JPG یا PNG میں بدلیں، پھر ڈی پی آئی لگائیں۔ اس ترتیب سے عدد درست جگہ محفوظ ہوتا ہے۔</p>\n<h2 id=\"before-not-set\">تصویریں پہلے کیوں دکھاتی ہیں: سیٹ نہیں ہوا</h2>\n<p>بہت سی تصویروں میں ڈی پی آئی لکھا ہی نہیں ہوتا، خاص طور پر فون یا اسکرین شاٹ سے لی گئی تصویروں میں۔ ٹول ایسی فائل کے لیے پہلے والی حالت میں سیٹ نہیں ہوا دکھاتا ہے۔</p>\n<p>اس کا مطلب یہ نہیں کہ تصویر خراب ہے، صرف یہ کہ پرنٹر کو کوئی ہدایت نہیں ملی۔ ڈی پی آئی لگا دینے سے پرنٹر کو صاف ہدایت مل جاتی ہے۔</p>\n<h2 id=\"verified-dpi-badge\">تصدیق شدہ ڈی پی آئی بیج</h2>\n<p>ڈی پی آئی لگانے کے بعد ٹول تصدیق شدہ بیج دکھاتا ہے، جو بتاتا ہے کہ عدد فائل میں درست لکھا گیا ہے۔ یہ بیج اس لیے اہم ہے کہ کچھ ٹول عدد بدلنے کا دعویٰ کرتے ہیں مگر فائل میں کچھ نہیں لکھتے۔</p>\n<p>فائل ڈاؤن لوڈ کرنے سے پہلے بیج جانچیں۔ اگر بیج نظر نہ آئے تو دوبارہ کوشش کریں یا فائل دوبارہ اپ لوڈ کریں۔</p>\n<h2 id=\"exif-and-icc-preservation\">EXIF ٹیگ اور ICC پروفائل محفوظ رہتے ہیں</h2>\n<p>ڈی پی آئی بدلتے وقت تصویر کا باقی میٹا ڈیٹا محفوظ رہتا ہے۔ کیمرے کی معلومات اور رنگ پروفائل نہیں مٹتے، صرف ڈی پی آئی والا عدد بدلتا ہے۔</p>\n<p>یہ اس لیے اہم ہے کہ رنگ پروفائل مٹ جانے سے تصویر کے رنگ بدل سکتے ہیں۔ ٹول صرف وہی عدد بدلتا ہے جو آپ نے بدلنے کو کہا ہے۔</p>\n<h2 id=\"png-299-vs-300\">PNG کبھی کبھی 299 ڈی پی آئی کیوں پڑھتا ہے</h2>\n<p>PNG ڈی پی آئی کو میٹر میں پکسلز کے طور پر محفوظ کرتا ہے، اور 300 ڈی پی آئی کو میٹر میں بدلنے پر عدد پورا نہیں بنتا۔ اس لیے کچھ پروگرام 300 کی جگہ 299 پڑھتے ہیں۔</p>\n<p>یہ کوئی غلطی نہیں ہے، صرف گول کرنے کا فرق ہے۔ زیادہ تر فارم 299 کو 300 کے برابر مانتے ہیں، اور پرنٹ پر کوئی فرق نہیں پڑتا۔</p>\n<h2 id=\"batch-zip-workflow\">بیچ پروسیسنگ اور ZIP برآمد</h2>\n<p>بیچ میں آپ بہت سی تصویروں کی ڈی پی آئی ایک ساتھ بدل سکتے ہیں۔ سب پر ایک ہی عدد لگتا ہے، اور نتیجہ ایک ZIP فائل میں ڈاؤن لوڈ ہوتا ہے۔</p>\n<p>یہ پوری کتاب یا کیٹلاگ تیار کرتے وقت بہت وقت بچاتا ہے۔ ZIP میں فائلوں کے نام وہی رہتے ہیں، اس لیے انہیں دوبارہ ترتیب دینے کی ضرورت نہیں پڑتی۔</p>\n<h2 id=\"dpi-and-file-size\">کیا ڈی پی آئی بدلنے سے فائل سائز بدلتا ہے؟</h2>\n<p>عملی طور پر نہیں۔ ڈی پی آئی صرف ایک چھوٹا سا عدد ہے، اس لیے فائل کا سائز تقریباً وہی رہتا ہے، چاہے آپ 72 لکھیں یا 600۔</p>\n<p>اگر فائل کا سائز بدلتا نظر آئے تو وجہ کچھ اور ہے، جیسے فارمیٹ بدلنا یا دوبارہ محفوظ کرنا۔ خالص ڈی پی آئی تبدیلی فائل کو ہلکی یا بھاری نہیں کرتی۔</p>\n<h2 id=\"why-platforms-reject-72-dpi\">پلیٹ فارم 72 ڈی پی آئی والی فائلیں کیوں مسترد کرتے ہیں</h2>\n<p>بہت سے سرکاری اور پرنٹ پلیٹ فارم کم سے کم 300 ڈی پی آئی مانگتے ہیں، کیونکہ وہ چاہتے ہیں کہ پرنٹ تیز ہو۔ 72 ڈی پی آئی والی فائل ان کے اصول سے باہر ہوتی ہے، چاہے پکسلز کافی ہوں۔</p>\n<p>حل سادہ ہے: ڈی پی آئی 300 لگا دیں۔ پکسلز وہی رہتے ہیں، مگر فائل اصول کے اندر آ جاتی ہے اور قبول ہو جاتی ہے۔</p>\n<h2 id=\"re-applying-dpi\">دوبارہ مختلف ڈی پی آئی لگانا</h2>\n<p>اگر آپ نے غلط ڈی پی آئی لگا دی ہو تو اسے دوبارہ بدلنا آسان ہے۔ اصل یا بدلی ہوئی فائل دوبارہ اپ لوڈ کریں اور نیا عدد لگائیں، پرانا عدد مٹ جاتا ہے۔</p>\n<p>بار بار ڈی پی آئی بدلنے سے تصویر کو کوئی نقصان نہیں ہوتا، کیونکہ پکسلز چھوئے ہی نہیں جاتے۔ یہ صرف میٹا ڈیٹا کی تبدیلی ہے۔</p>\n<h2 id=\"how-to-use-the-tool\">امیج ڈی پی آئی چینجر کیسے استعمال کریں</h2>\n<p>تصویر اپ لوڈ کریں، پہلے سے طے شدہ عدد چنیں یا اپنی مرضی کا عدد لکھیں، اور تصدیق شدہ بیج دیکھ کر ڈاؤن لوڈ کریں۔ بیچ کے لیے کئی تصویریں ایک ساتھ ڈالیں اور ZIP لیں۔</p>\n<p>ڈی پی آئی اور پی پی آئی کے فرق کے لیے <a href=\"/ur/blog/dpi-vs-ppi-print-web/\">ڈی پی آئی بمقابلہ پی پی آئی</a> اور عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-ka-dpi-kaise-badlein/\">تصویر کی ڈی پی آئی کیسے بدلیں</a> پڑھیں۔ ابعاد جانچنے کے لیے <a href=\"/ur/tasveer-ka-size-dekhein/\">ڈائمینشنز چیکر</a> اور میٹا ڈیٹا صاف کرنے کے لیے <a href=\"/ur/tasveer-metadata-hatayein/\">میٹا ڈیٹا ہٹانے</a> کا ٹول دیکھیں۔</p>\n";

